 fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.multi.terminal_is_empty(){return self.multi.close_demand(body)}if !self.post.terminal_is_empty(){return self.post.close_demand(body)}if !self.original.terminal_is_empty(){return self.original.close_demand(body)}if let Some(r)=self.text_receiver.as_ref(){return if r.terminal_is_empty(){Ok(fixed(2*size_of::<Option<TextReceiver>>()))}else{r.close_demands(body)}}if !self.fill_receiver.terminal_is_empty(){return self.fill_receiver.close_demand(body)}if !self.stroke_receiver.terminal_is_empty(){return self.stroke_receiver.close_demand(body)}if !self.segments_receiver.terminal_is_empty(){return self.segments_receiver.close_demand(body)}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<Displaced>(false,&None,body)}if self.trash.is_some(){return self.retirement.next_owner_demands::<Displaced>(true,&None,body)}if self.ready_text.is_some(){return self.retirement.next_owner_demands::<Text>(true,&None,body)}if self.ready_fill.is_some(){return self.retirement.next_owner_demands::<Option<FillStyle>>(true,&None,body)}if self.ready_stroke.is_some(){return self.retirement.next_owner_demands::<Option<StrokeStyle>>(true,&None,body)}if self.ready_segments.is_some(){return self.retirement.next_owner_demands::<Segments>(true,&None,body)}Ok(Default::default())}
